+function formatTemplateVars(template, vars) {
+    var result = template;
+    for (var key in vars) {
+        if (vars.hasOwnProperty(key)) {
+            var placeholder = '{' + key + '}';
+            while (result.indexOf(placeholder) !== -1) {
